function writeResolution(alias: string, canonical: string, verdict: string, reasoning: string, run: string): void {
  try {
    db.prepare('INSERT OR REPLACE INTO resolutions (alias, canonical_id, verdict, reasoning, created_run) VALUES (?,?,?,?,?)').run(alias, canonical, verdict, reasoning, run);
  } catch (e: unknown) {
    throw new ResolverError(`RESOLVER_FAILED: resolutions write failed for alias=${alias} — ${e instanceof Error ? e.message : String(e)}`);
  }
}
for (const d of decisions) {
  let target = d.canonicalId;
  if (d.verdict === 'unrelated' && d.destructive) {
    target = d.alias;
  } else if (d.verdict === 'same') {
    target = d.existingCanonical ? d.existingCanonical.canonical_id : d.canonicalId;
  }
  writeResolution(d.alias, target, d.verdict, d.reasoning, runId);
}

