if (!Array.isArray(existing)) throw new ResolverError('RESOLVER_FAILED: existing must be an array');
// Short-circuit: no existing canonicals means every entity is unrelated — skip harness.
if (existing.length === 0) {
  return newEntities.map((ne) => ({
    alias: ne.id, canonicalId: ne.id, verdict: 'unrelated' as ResolutionVerdict,
    reasoning: `no existing canonicals — "${ne.label}" is new`, destructive: false,
    newEntity: ne, existingCanonical: null,
  }));
}

